/* eslint no-console:0 import/extensions:0 */
import 'fantd/src/tab/style/index.less';
import { Tab } from 'fantd';
import React from 'react';
import ReactDOM from 'react-dom';

const Button = Tab.Button;

class Component extends React.Component {

    render() {
        return (
            <div>
                <Tab size="small">
                    <Button value="1">1</Button>
                    <Button value="2">2</Button>
                </Tab>
                <br />
                <br />
                <Tab>
                    <Button value="1">1</Button>
                    <Button value="2">2</Button>
                </Tab>
                <br />
                <br />
                <Tab size="large">
                    <Button value="1">1</Button>
                    <Button value="2">2</Button>
                </Tab>
                <br />
                <br />
                <Tab disabled value='2'>
                    <Button value="1">1</Button>
                    <Button value="2">2</Button>
                </Tab>
                <br />
                <br />
                <Tab size="small"  disabled value='2'>
                    <Button value="1">1</Button>
                    <Button value="2">2</Button>
                </Tab>
                <br />
                <br />
                <Tab  size="large" disabled value='2'>
                    <Button value="1">1</Button>
                    <Button value="2">2</Button>
                </Tab>
                <br />
                <br />
                <Tab size="large">
                    <Button value="1" style={{width: 100}}>11111111111111111111111111111</Button>
                    <Button value="2" style={{width: 100}}>2</Button>
                </Tab>
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



